function c($){if(!$)return"Recently";const a=new Date($).getTime();if(isNaN(a))return"Recently";const i=Date.now();let t=Math.floor((i-a)/1e3),o=" ago";if(t<0&&(t=Math.abs(t),o=" from now"),t<10)return"Just now";if(t<60)return`${t} second${t!==1?"s":""}${o}`;const r=Math.floor(t/60);if(r<60)return`${r} minute${r!==1?"s":""}${o}`;const n=Math.floor(t/3600);if(n<24)return`${n} hour${n!==1?"s":""}${o}`;const e=Math.floor(t/86400);if(e<7)return`${e} day${e!==1?"s":""}${o}`;const s=Math.floor(e/7);if(s<4)return`${s} week${s!==1?"s":""}${o}`;const f=Math.floor(e/30);if(f<12)return`${f} month${f!==1?"s":""}${o}`;const u=Math.floor(e/365);return`${u} year${u!==1?"s":""}${o}`}export{c as t};
